<?php
if (!defined('ABSPATH')) { exit; }

class KornSW_PayedStreams_Rest
{
    private $Repository; private $Access;
    public function __construct($Repository){$this->Repository=$Repository;$this->Access=new KornSW_PayedStreams_Access($Repository);}
    public function Register(){add_action('rest_api_init',array($this,'Routes'));}
    public function Routes(){register_rest_route('kornsw-payedstreams/v1','/play/(?P<video>[A-Za-z0-9\-]+)',array('methods'=>'GET','callback'=>array($this,'Play'),'permission_callback'=>'__return_true'));register_rest_route('kornsw-payedstreams/v1','/progress',array('methods'=>'POST','callback'=>array($this,'Progress'),'permission_callback'=>'__return_true'));register_rest_route('kornsw-payedstreams/v1','/click',array('methods'=>'POST','callback'=>array($this,'Click'),'permission_callback'=>'__return_true'));register_rest_route('kornsw-payedstreams/v1','/refresh-purchases',array('methods'=>'POST','callback'=>array($this,'RefreshPurchases'),'permission_callback'=>array($this,'MustBeLoggedIn')));register_rest_route('kornsw-payedstreams/v1','/product/(?P<product>[A-Za-z0-9\-]+)',array('methods'=>'GET','callback'=>array($this,'ProductLive'),'permission_callback'=>'__return_true'));}
    public function MustBeLoggedIn(){return is_user_logged_in();}
    public function Play($Request){$Id=sanitize_text_field($Request['video']);$V=$this->Repository->GetVideo($Id);if(!$V)return new WP_Error('not_found','Inhalt nicht gefunden.',array('status'=>404));if($V['source_type']==='post')return new WP_Error('not_playable','Dieser Inhalt wird als Beitrag geöffnet.',array('status'=>400));$D=$this->Access->CanView($Id);if(!$D['allowed'])return new WP_Error('forbidden','Für dieses Video besteht aktuell keine Berechtigung.',array('status'=>403));try{$Url='';$Type=$V['source_type'];if($Type==='bunny'||$Type===''){$Url=(new KornSW_PayedStreams_Bunny_Client())->CreateSignedEmbedUrl($Id,$Request->get_param('autoplay')==='1');$Type='bunny';}else{$Url=$V['content_url'];if(!$Url)throw new Exception('Lokale Video-URL fehlt.');}$Progress=is_user_logged_in()?$this->Repository->GetProgress(get_current_user_id(),$Id):null;return rest_ensure_response(array('url'=>$Url,'type'=>$Type,'title'=>$V['title'],'progress'=>$Progress,'reason'=>$D['reason']));}catch(Exception$Ex){KornSW_PayedStreams_Logger::Exception('Player',$Ex,array('video_id'=>$Id,'source_type'=>$V['source_type']));return new WP_Error('stream_unavailable','Video vorübergehend nicht verfügbar.',array('status'=>503));}}
    public function Progress($Request){$Data=$Request->get_json_params();if(!is_array($Data))$Data=$Request->get_params();$Id=sanitize_text_field(isset($Data['video'])?$Data['video']:'');$Pos=max(0,intval(isset($Data['position'])?$Data['position']:0));$Dur=max(0,intval(isset($Data['duration'])?$Data['duration']:0));$Qualified=!empty($Data['qualified']);$Completed=!empty($Data['completed'])||($Dur>0&&($Pos/$Dur)>=0.95);$V=$this->Repository->GetVideo($Id);if(!$Id||!$V||$V['source_type']==='post')return new WP_Error('invalid_video','Ungültiges Video.',array('status'=>400));$D=$this->Access->CanView($Id);if(!$D['allowed'])return new WP_Error('forbidden','Keine Berechtigung.',array('status'=>403));if(is_user_logged_in()){$this->Repository->SaveProgress(get_current_user_id(),$Id,$Pos,$Dur,$Qualified,$Completed);}elseif($Qualified){$Cookie=isset($_COOKIE['kornsw_ps_sid'])?sanitize_text_field(wp_unslash($_COOKIE['kornsw_ps_sid'])):'';if($Cookie===''){$Cookie=wp_generate_uuid4();setcookie('kornsw_ps_sid',$Cookie,time()+YEAR_IN_SECONDS,COOKIEPATH?:'/',COOKIE_DOMAIN,is_ssl(),true);}$this->Repository->RecordAnonymousView($Id,hash('sha256',$Cookie.wp_salt('nonce')));}return rest_ensure_response(array('ok'=>true));}
    public function Click($Request){$Data=$Request->get_json_params();if(!is_array($Data))$Data=$Request->get_params();$Id=sanitize_text_field(isset($Data['content'])?$Data['content']:'');$V=$this->Repository->GetVideo($Id);if(!$Id||!$V||$V['source_type']!=='post')return new WP_Error('invalid_content','Ungültiger externer Inhalt.',array('status'=>400));$D=$this->Access->CanView($Id);if(!$D['allowed'])return new WP_Error('forbidden','Keine Berechtigung.',array('status'=>403));$Cookie=isset($_COOKIE['kornsw_ps_sid'])?sanitize_text_field(wp_unslash($_COOKIE['kornsw_ps_sid'])):'';if($Cookie===''){$Cookie=wp_generate_uuid4();setcookie('kornsw_ps_sid',$Cookie,time()+YEAR_IN_SECONDS,COOKIEPATH?:'/',COOKIE_DOMAIN,is_ssl(),true);}$this->Repository->RecordContentClick($Id,get_current_user_id(),$Cookie);return rest_ensure_response(array('ok'=>true));}
    public function RefreshPurchases($Request){$User=wp_get_current_user();try{(new KornSW_PayedStreams_Digistore_Client())->SyncUserPurchases($User->ID,$User->user_email,$this->Repository);return rest_ensure_response(array('ok'=>true,'products'=>$this->Repository->GetValidProductIdsForUser($User->ID)));}catch(Exception$Ex){KornSW_PayedStreams_Logger::Exception('Digistore24',$Ex,array('user_id'=>$User->ID));return new WP_Error('digistore_unavailable','Kaufprüfung vorübergehend nicht möglich. Vorhandene Freischaltungen bleiben erhalten.',array('status'=>503));}}
    public function ProductLive($Request){$Id=sanitize_text_field($Request['product']);$Cached=$this->Repository->GetProduct($Id);if(!$Cached)return new WP_Error('not_found','Produkt nicht gefunden.',array('status'=>404));try{$Live=(new KornSW_PayedStreams_Digistore_Client())->GetProduct($Id);if($Live){$this->Repository->UpsertProduct($Live);$Cached=$this->Repository->GetProduct($Id);}}catch(Exception$Ex){KornSW_PayedStreams_Logger::Exception('Digistore24',$Ex,array('product_id'=>$Id,'fallback'=>'cache'));}return rest_ensure_response($this->PublicProduct($Cached));}
    private function PublicProduct($P){$Description=trim((string)$P['description_override'])!==''?$P['description_override']:$P['description'];$Checkout=(new KornSW_PayedStreams_Digistore_Client())->NormalizeCheckoutUrl($P['checkout_url'],$P['external_id']);return array('id'=>$P['external_id'],'name'=>$P['name'],'description'=>wp_strip_all_tags($Description),'price'=>$P['price_display'],'checkout_url'=>$Checkout,'featured'=>intval($P['featured'])===1);}
}
